patterns.wrong:
// No .menu file opened, but waiting for menuresponse:
for (;;)
{
    self waittill("menuresponse", menu, response);
    // this never fires
}

patterns.right:
// menuresponse only fires when a native .menu file sends scriptMenuResponse.
// First open the menu:
self openMenu(game["myMenu"]);
// Then wait:
self waittill("menuresponse", menu, response);

