patterns.wrong:
self waittill("menuresponse", menu, response);
switch (response)
{
    case "option1":
        doSomething();
        break;
    case "option2":
        doOther();
        break;
    // no default — CRASHES CoD4
}

patterns.right:
self waittill("menuresponse", menu, response);
switch (response)
{
    case "option1":
        doSomething();
        break;
    case "option2":
        doOther();
        break;
    default:
        break; // required in CoD4/IW3
}

patterns.wrong:
for (;;)
{
    self waittill("menu_up");
    scrollUp();
    wait 0; // can freeze or over-fire
}

patterns.right:
for (;;)
{
    self waittill("menu_up");
    scrollUp();
    wait 0.05; // debounce: ~3 frames at 60fps
}

patterns.wrong:
closeMenu()
{
    self.menuOpen = false;
    // forgot to destroy elements — they stay on screen
}

patterns.right:
closeMenu()
{
    self.menuOpen = false;
    if (isDefined(self.menuBg))     self.menuBg destroy();
    if (isDefined(self.menuTitle))  self.menuTitle destroy();
    if (isDefined(self.menuCursor)) self.menuCursor destroy();
    for (i = 0; i < self.menuOpts.size; i++)
        if (isDefined(self.menuOpts[i])) self.menuOpts[i] destroy();
}

patterns.wrong:
// In a CoD4 (IW3) script:
self notifyOnPlayerCommand("menu_up", "+actionslot 3");
self waittill("menu_up"); // notifyOnPlayerCommand doesn't exist in IW3

patterns.right:
// CoD4/IW3: use a compiled .menu file for key detection.
// In your .menu file:
// execKey "UPARROW" { scriptMenuResponse "up"; }
// In GSC:
self openMenu(game["myMenu"]);
self waittill("menuresponse", menu, response);
if (response == "up") scrollUp();

// In your init() / onPlayerConnect, before the menu is ever needed:
precacheMenu(game["myMenu"]);
// Later, during gameplay:
self openMenu(game["myMenu"]);
